import type { InteractionSnapshot, ProcessClient } from '@wright/process-client';
import { ProcessUI, Section, ProgressPanel, ResultCard, ReasonNotice } from '@wright/ui-kit';

export interface AppProps {
  client: ProcessClient;
  snapshot: InteractionSnapshot;
  readOnly: boolean;
}

type ExtendedSnapshot = InteractionSnapshot & {
  findings?: unknown[];
  pending_interactions?: unknown[];
};

export default function App({ snapshot, readOnly }: AppProps) {
  const current = snapshot as ExtendedSnapshot;
  const outputs = snapshot.outputs ?? [];
  const marker = (output: unknown) => JSON.stringify(output).toLowerCase();
  const baseline = outputs.filter(output => marker(output).includes('baseline_40'));
  const revision = outputs.filter(output => marker(output).includes('revision_60'));
  const compared = new Set([...baseline, ...revision]);
  const shared = outputs.filter(output => !compared.has(output));
  const pending = current.pending_interactions ?? [];
  const findings = current.findings ?? [];

  return <ProcessUI>
    <Section title="Heat-spreader candidate comparison">
      {readOnly && <p>Preview — review the interface before using the process.</p>}
      <ProgressPanel state={snapshot.state} observations={snapshot.observations ?? []} />
      {(snapshot.diagnostics ?? []).map((reason, index) =>
        <ReasonNotice key={`${reason.code}-${index}`} reason={reason} />)}
    </Section>
    <Section title="Candidate results">
      {outputs.length === 0 && <p>Results will appear as the process produces them.</p>}
      <table>
        <caption>Current results grouped by recorded candidate identity</caption>
        <thead><tr><th scope="col">Baseline 40</th><th scope="col">Revision 60</th></tr></thead>
        <tbody><tr>
          <td>{baseline.map(output => <ResultCard key={output.result_id} output={output} />)}</td>
          <td>{revision.map(output => <ResultCard key={output.result_id} output={output} />)}</td>
        </tr></tbody>
      </table>
      {shared.length > 0 && <section aria-labelledby="shared-results">
        <h3 id="shared-results">Shared evidence and checks</h3>
        {shared.map(output => <ResultCard key={output.result_id} output={output} />)}
      </section>}
    </Section>
    <Section title="Pending findings and review">
      {findings.length === 0 && pending.length === 0 &&
        <p>No pending findings or review interactions are reported in the current snapshot.</p>}
      {findings.map((finding, index) => <pre key={`finding-${index}`}>{JSON.stringify(finding, null, 2)}</pre>)}
      {pending.map((interaction, index) => <pre key={`review-${index}`}>{JSON.stringify(interaction, null, 2)}</pre>)}
      <p>No artifact-specific viewer or mutation control is included in this compact comparison.</p>
    </Section>
  </ProcessUI>;
}
